const sampleItem = await browserjs(tabId, () => {
  // Let's find the course items
  // Let's inspect elements around the H2 headers
  const h2s = Array.from(document.querySelectorAll('h2')).filter(h => !/menu|navigation|search/i.test(h.textContent));
  return h2s.map(h => {
    const card = h.closest('.search-result, .views-row, div[data-json], article, li, div') || h.parentElement;
    // Let's find the container that holds this class
    let container = h;
    while (container && !container.classList.contains('search-result') && !container.classList.contains('views-row') && container !== document.body) {
      container = container.parentElement;
    }
    return {
      title: h.textContent.trim(),
      containerClass: container ? container.className : null,
      containerText: container ? container.innerText.slice(0, 500) : h.parentElement.innerText.slice(0, 500)
    };
  });
});

