const tabId = 118779795;

// Navigate back to the CS grad courses in Fall 2023
const csGradUrl = "https://classes.berkeley.edu/search/class?f[0]=term:7697&f[1]=subject_area:5582&f[2]=course_level:grad";
await tool.navigate({ tabId, url: csGradUrl });
await tool.wait_for({ tabId, condition: "load_state", value: "load", timeout_ms: 15000 });

// Let's click "expanded" view to see if all sections (discussions, labs) are shown!
const expandedBtn = await browserjs(tabId, () => {
  const btn = document.querySelector('button[title*="expanded"], a[title*="expanded"], .facetapi-collapsible-btn, #btn-show-expanded');
  // Look for button with text 'expanded'
  const allBtns = Array.from(document.querySelectorAll('button, a'));
  const target = allBtns.find(b => b.textContent.trim().toLowerCase() === 'expanded');
  if (target) {
    target.click();
    return { clicked: true, text: target.textContent };
  }
  return { clicked: false };
});

console.log("Clicked expanded button:", expandedBtn);
await tool.wait_for({ tabId, condition: "dom_settled", timeout_ms: 3000 });

const expandedContent = await browserjs(tabId, () => {
  // Check if any sections (DIS, LAB, etc.) appear
  const text = document.body.innerText;
  const hasDis = /DIS\s+\d+|Discussion/i.test(text);
  const hasLab = /LAB\s+\d+|Laboratory/i.test(text);
  return { hasDis, hasLab };
});

console.log("Expanded content check:", expandedContent);

